def solve(s):
    if not any(char.isalpha() for char in s):
        return s[::-1]
    else:
        return ''.join([char.upper() if char.islower() else char.lower() for char in s])

def largest_smallest_integers(lst):
    neg_nums = [i for i in lst if i < 0]
    pos_nums = [i for i in lst if i > 0]

    if not neg_nums:
        a = None
    else:
        a = max(neg_nums)

    if not pos_nums:
        b = None
    else:
        b = min(pos_nums)

    return (a, b)

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    factors = []
    for i in range(2, a):
        if a % i == 0 and is_prime(i):
            factors.append(i)

    if len(factors) == 3 and factors[0] * factors[1] * factors[2] == a:
        return True
    else:
        return False

def bf(planet1, planet2):
    planets = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune']
    if planet1 not in planets or planet2 not in planets:
        return ()
    else:
        start = min(planets.index(planet1), planets.index(planet2))
        end = max(planets.index(planet1), planets.index(planet2))
        return tuple(planets[start+1:end])

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]
    return ""

def is_sorted(lst):
    if len(lst) == 1:
        return True
    else:
        for i in range(len(lst) - 1):
            if lst[i] >= lst[i + 1]:
                return False
        return True

def maximum(arr, k):
    arr.sort(reverse=True)
    return arr[:k]
